<?php\n/**\n * Script individual para busca de imagens\n * Este script executa apenas a busca e download de imagens do site CCCRJ\n */\n\n// Incluir o arquivo com a definição da classe (sem execução automática)\n$content = file_get_contents('image_finder.php');\n\n// Remover a execução automática no final do arquivo\n$content = preg_replace('/\\?>.*\\$imageFinder = new ImageFinder\\(\\);.*\\$imageFinder->findAndDownloadImages\\(\\);/s', '?>', $content);\n\n// Salvar temporariamente\nfile_put_contents('temp_image_finder.php', $content);\n\n// Incluir a classe\ninclude_once 'temp_image_finder.php';\n\n// Criar e executar o finder de imagens\n$imageFinder = new ImageFinder();\n$imageFinder->findAndDownloadImages();\n\n// Remover o arquivo temporário\nunlink('temp_image_finder.php');\n?>